{
  "name": "SembakoPOS - Solusi Kasir Toko Kelontong",
  "description": "A modern, fast, and user-friendly Point of Sale (POS) system specifically designed for grocery stores (toko sembako) with inventory management, transaction tracking, and thermal receipt printing."
}

export enum UnitType {
  KG = 'kg',
  GRAM = 'gr',
  PCS = 'pcs',
  DUS = 'dus',
  LITER = 'liter'
}

export enum PaymentMethod {
  CASH = 'Tunai',
  QRIS = 'QRIS',
  TRANSFER = 'Transfer Bank'
}

export interface Product {
  id: string;
  name: string;
  price: number;
  stock: number;
  unit: UnitType;
  category: string;
  minStock: number;
  imageUrl?: string;
}

export interface CartItem extends Product {
  quantity: number;
}

export interface Transaction {
  id: string;
  date: string;
  items: CartItem[];
  total: number;
  paymentMethod: PaymentMethod;
  amountPaid: number;
  change: number;
}

export type AppView = 'dashboard' | 'cashier' | 'inventory' | 'history';

export const formatCurrency = (amount: number): string => {
  return new Intl.NumberFormat('id-ID', {
    style: 'currency',
    currency: 'IDR',
    minimumFractionDigits: 0,
  }).format(amount);
};

export const formatDate = (dateString: string): string => {
  return new Date(dateString).toLocaleDateString('id-ID', {
    day: 'numeric',
    month: 'short',
    year: 'numeric',
    hour: '2-digit',
    minute: '2-digit',
  });
};

export const generateId = () => Math.random().toString(36).substr(2, 9).toUpperCase();

export const exportToCSV = (data: any[], filename: string) => {
  if (data.length === 0) return;
  const headers = Object.keys(data[0]).join(',');
  const rows = data.map(obj => Object.values(obj).map(val => `"${val}"`).join(','));
  const csvContent = "data:text/csv;charset=utf-8," + headers + "\n" + rows.join("\n");
  const encodedUri = encodeURI(csvContent);
  const link = document.createElement("a");
  link.setAttribute("href", encodedUri);
  link.setAttribute("download", filename);
  document.body.appendChild(link);
  link.click();
  document.body.removeChild(link);
};

