            <div className="flex-1 overflow-y-auto p-8 space-y-8 custom-scrollbar">
              <div className="text-center">
                <p className="text-gray-500 mb-1">Total Tagihan</p>
                <p className="text-4xl font-black text-blue-600">{formatCurrency(cartTotal)}</p>
              </div>

              <div className="grid grid-cols-3 gap-3">
                {[
                  { id: PaymentMethod.CASH, label: 'Tunai', icon: Banknote },
                  { id: PaymentMethod.QRIS, label: 'QRIS', icon: QrCode },
                  { id: PaymentMethod.TRANSFER, label: 'Digital/Transfer', icon: Send },
                ].map(method => (
                  <button
                    key={method.id}
                    onClick={() => {
                      setPaymentMethod(method.id as PaymentMethod);
                      setSelectedProvider('');
                    }}
                    className={`flex flex-col items-center gap-2 p-4 rounded-2xl border-2 transition-all ${
                      paymentMethod === method.id 
                        ? 'border-blue-600 bg-blue-50 text-blue-600' 
                        : 'border-gray-100 text-gray-400 hover:border-blue-200'
                    }`}
                  >
                    <method.icon size={24} />
                    <span className="text-xs font-bold">{method.label}</span>
                  </button>
                ))}
              </div>

              {/* CASH SECTION */}
              {paymentMethod === PaymentMethod.CASH && (
                <div className="space-y-4 animate-in fade-in slide-in-from-top-2">
                  <div className="grid grid-cols-3 gap-2">
                    {quickDenominations.map(val => (
                      <button 
                        key={val}
                        onClick={() => addDenomination(val)}
                        className="py-2 bg-gray-50 hover:bg-blue-100 text-gray-700 font-bold rounded-xl border border-gray-100 text-sm transition-all"
                      >
                        +{val/1000}rb
                      </button>
                    ))}
                    <button 
                      onClick={() => setAmountPaid(cartTotal.toString())}
                      className="py-2 bg-blue-50 hover:bg-blue-100 text-blue-600 font-bold rounded-xl border border-blue-100 text-sm col-span-3 transition-all"
                    >
                      Uang Pas ({formatCurrency(cartTotal)})
                    </button>
                  </div>
                  <div className="space-y-2">
                    <label className="text-sm font-semibold text-gray-700">Nominal Tunai</label>
                    <div className="relative">
                      <span className="absolute left-4 top-1/2 -translate-y-1/2 font-bold text-gray-400">Rp</span>
                      <input
                        type="number"
                        autoFocus
                        placeholder="0"
                        className="w-full p-4 pl-12 bg-gray-50 border border-gray-200 rounded-2xl focus:outline-none focus:ring-2 focus:ring-blue-500 font-bold text-xl text-right text-gray-900"
                        value={amountPaid}
                        onChange={(e) => setAmountPaid(e.target.value)}
                      />
                    </div>
                    {Number(amountPaid) >= cartTotal && (
                      <div className="flex justify-between items-center px-2 bg-green-50 p-3 rounded-xl border border-green-100">
                        <span className="text-sm text-green-700 font-medium">Kembalian:</span>
                        <span className="font-bold text-green-700 text-lg">{formatCurrency(change)}</span>
                      </div>
                    )}
                  </div>
                </div>
              )}

              {/* QRIS SECTION */}
              {paymentMethod === PaymentMethod.QRIS && (
                <div className="flex flex-col items-center gap-6 animate-in fade-in slide-in-from-top-2">
                  <div className="p-4 bg-white border-4 border-gray-100 rounded-3xl shadow-inner relative overflow-hidden group">
                    {/* Simulated QR Code */}
                    <div className="w-48 h-48 bg-gray-50 flex items-center justify-center border-2 border-dashed border-gray-200 rounded-2xl">
                       <QrCode size={120} className="text-gray-300" />
                       <div className="absolute inset-0 flex items-center justify-center">
                          <div className="w-40 h-40 bg-[url('https://api.qrserver.com/v1/create-qr-code/?size=160x160&data=SembakoPOS-Trx')] bg-center bg-no-repeat opacity-90"></div>
                       </div>
                    </div>
                    <div className="absolute top-2 left-2 right-2 flex justify-between px-2">
                       <span className="text-[8px] font-bold text-gray-400">QRIS STANDAR</span>
                       <span className="text-[8px] font-bold text-gray-400">INDONESIA</span>
                    </div>
                  </div>
                  <div className="text-center space-y-1">
                    <p className="text-sm font-bold text-gray-700 uppercase tracking-widest">Pindai Untuk Membayar</p>
                    <p className="text-xs text-gray-400">Silahkan arahkan kamera aplikasi ke kode di atas</p>
                  </div>
                </div>
              )}

              {/* TRANSFER SECTION */}
              {paymentMethod === PaymentMethod.TRANSFER && (
                <div className="space-y-6 animate-in fade-in slide-in-from-top-2">
                  <div className="space-y-3">
                    <div className="flex items-center gap-2 text-gray-500 text-sm font-bold">
                      <Building2 size={16} />
                      BANK TRANSFER
                    </div>
                    <div className="grid grid-cols-2 gap-2">
                      {banks.map(bank => (
                        <button
                          key={bank}
                          onClick={() => setSelectedProvider(bank)}
                          className={`p-3 rounded-xl border-2 font-bold text-sm transition-all ${
                            selectedProvider === bank ? 'border-blue-600 bg-blue-50 text-blue-600' : 'border-gray-50 text-gray-500 hover:border-gray-200'
                          }`}
                        >
                          {bank}
                        </button>
                      ))}
                    </div>
                  </div>

                  <div className="space-y-3">
                    <div className="flex items-center gap-2 text-gray-500 text-sm font-bold">
                      <Wallet size={16} />
                      DOMPET DIGITAL
                    </div>
                    <div className="grid grid-cols-2 gap-2">
                      {ewallets.map(wallet => (
                        <button
                          key={wallet}
                          onClick={() => setSelectedProvider(wallet)}
                          className={`p-3 rounded-xl border-2 font-bold text-sm transition-all ${
                            selectedProvider === wallet ? 'border-blue-600 bg-blue-50 text-blue-600' : 'border-gray-50 text-gray-500 hover:border-gray-200'
                          }`}
                        >
                          {wallet}
                        </button>
                      ))}
                    </div>
                  </div>
                </div>
              )}
            </div>

            <div className="p-6 border-t border-gray-100 bg-gray-50">
              <button
                onClick={handleCheckout}
                className="w-full py-4 bg-blue-600 text-white rounded-2xl font-bold text-xl shadow-lg hover:bg-blue-700 transition-all flex items-center justify-center gap-3 active:scale-[0.98]"
              >
                Konfirmasi Pembayaran
                <CheckCircle2 size={24} />
              </button>
            </div>
          </div>
        </div>
      )}

      {/* Success View / Last Transaction for Printing */}
      {lastTransaction && !showCheckoutModal && (
        <div className="fixed inset-0 bg-white z-[60] flex flex-col items-center justify-center p-6 no-print">
          <div className="text-center mb-8">
            <div className="w-20 h-20 bg-green-100 text-green-600 rounded-full flex items-center justify-center mx-auto mb-4 animate-bounce">
              <CheckCircle2 size={48} />
            </div>
            <h2 className="text-3xl font-bold text-gray-800">Pembayaran Berhasil!</h2>
            <p className="text-gray-500 mt-2">Nomor Transaksi: {lastTransaction.id}</p>
            <div className="mt-2 px-3 py-1 bg-blue-50 text-blue-600 rounded-full text-xs font-bold inline-block">
               {lastTransaction.paymentMethod} {lastTransaction.paymentProvider !== 'Tunai' ? `(${lastTransaction.paymentProvider})` : ''}
            </div>
          </div>

          <div className="bg-gray-50 p-6 rounded-3xl border border-gray-100 w-full max-w-sm mb-8">
             <div className="flex justify-between mb-2">
                <span className="text-gray-500">Total</span>
                <span className="font-bold text-gray-900">{formatCurrency(lastTransaction.total)}</span>
             </div>
             <div className="flex justify-between mb-2">
                <span className="text-gray-500">Bayar</span>
                <span className="font-bold text-gray-900">{formatCurrency(lastTransaction.amountPaid)}</span>
             </div>
             <div className="flex justify-between pt-2 border-t border-gray-200">
                <span className="text-gray-500">Kembali</span>
                <span className="font-bold text-green-600">{formatCurrency(lastTransaction.change)}</span>
             </div>
          </div>

          <div className="flex gap-4 w-full max-w-sm">
            <button
              onClick={printReceipt}
              className="flex-1 flex items-center justify-center gap-2 py-4 border-2 border-blue-600 text-blue-600 rounded-2xl font-bold hover:bg-blue-50 transition-all"
            >
              <Printer size={20} />
              Cetak Struk
            </button>
            <button
              onClick={() => setLastTransaction(null)}
              className="flex-1 py-4 bg-blue-600 text-white rounded-2xl font-bold hover:bg-blue-700 transition-all"
            >
              Transaksi Baru
            </button>
          </div>
        </div>
      )}

      {/* Hidden area for print receipt */}
      {lastTransaction && (
        <div className="print-only fixed top-0 left-0 bg-white w-full h-full z-[100]">
          <Receipt transaction={lastTransaction} />
        </div>
      )}
    </div>
  );
};

export default Cashier;

import React, { useState, useMemo } from 'react';
import { PackagePlus, Edit2, ArrowUpDown, Filter, Trash2, Search, Plus, Check, ChevronDown, SortAsc, SortDesc } from 'lucide-react';
import { Product, UnitType } from '../types';
import { formatCurrency } from '../utils';

interface InventoryProps {
  products: Product[];
  onAddStock: (id: string, amount: number) => void;
  onUpdateProduct: (product: Product) => void;
}

type SortOrder = 'asc' | 'desc' | 'none';

const Inventory: React.FC<InventoryProps> = ({ products, onAddStock, onUpdateProduct }) => {
  const [searchTerm, setSearchTerm] = useState('');
  const [editingId, setEditingId] = useState<string | null>(null);
  const [stockAmount, setStockAmount] = useState<string>('');
  const [selectedCategory, setSelectedCategory] = useState<string>('Semua');
  const [sortOrder, setSortOrder] = useState<SortOrder>('none');
  const [showCategoryMenu, setShowCategoryMenu] = useState(false);

  // Extract unique categories
  const categories = useMemo(() => {
    const cats = Array.from(new Set(products.map(p => p.category)));
    return ['Semua', ...cats];
  }, [products]);

  // Combined logic for Search, Filter, and Sort
  const processedProducts = useMemo(() => {
    let result = products.filter(p => {
      const matchesSearch = p.name.toLowerCase().includes(searchTerm.toLowerCase());
      const matchesCategory = selectedCategory === 'Semua' || p.category === selectedCategory;
      return matchesSearch && matchesCategory;
    });

    if (sortOrder === 'asc') {
      result.sort((a, b) => a.name.localeCompare(b.name));
    } else if (sortOrder === 'desc') {
      result.sort((a, b) => b.name.localeCompare(a.name));
    }

    return result;
  }, [products, searchTerm, selectedCategory, sortOrder]);

  const handleUpdateStock = (id: string) => {
    const amt = Number(stockAmount);
    if (!isNaN(amt) && amt !== 0) {
      onAddStock(id, amt);
      setEditingId(null);
      setStockAmount('');
    }
  };

  const toggleSort = () => {
    setSortOrder(prev => {
      if (prev === 'none') return 'asc';
      if (prev === 'asc') return 'desc';
      return 'none';
    });
  };

  return (
    <div className="space-y-6 animate-in fade-in duration-500">
      <header className="flex flex-col md:flex-row md:items-center justify-between gap-4">
        <div>
          <h2 className="text-2xl font-bold text-gray-800">Manajemen Stok</h2>
          <p className="text-gray-500">Kelola ketersediaan barang di gudang.</p>
        </div>
        <div className="flex gap-2">
           <button className="flex items-center gap-2 px-4 py-2 bg-blue-600 text-white rounded-xl font-bold shadow-lg shadow-blue-100 hover:bg-blue-700 transition-all">
             <PackagePlus size={18} />
             Tambah Produk Baru
           </button>
        </div>
      </header>

      <div className="bg-white rounded-3xl border border-gray-100 shadow-sm overflow-hidden">
        <div className="p-6 border-b border-gray-100 flex flex-col md:flex-row gap-4 items-center justify-between">
          <div className="relative w-full md:w-96">
            <Search className="absolute left-4 top-1/2 -translate-y-1/2 text-gray-400" size={18} />
            <input 
              type="text" 
              placeholder="Cari di inventori..."
              className="w-full pl-11 pr-4 py-2.5 bg-gray-50 border border-transparent rounded-xl focus:border-blue-500 focus:outline-none transition-all text-gray-900"
              value={searchTerm}
              onChange={(e) => setSearchTerm(e.target.value)}
            />
          </div>
          <div className="flex gap-2 relative w-full md:w-auto">
            {/* Category Filter Dropdown */}
            <div className="relative flex-1 md:flex-none">
              <button 
                onClick={() => setShowCategoryMenu(!showCategoryMenu)}
                className={`w-full flex items-center justify-between gap-2 px-4 py-2.5 rounded-xl transition-all border ${
                  selectedCategory !== 'Semua' 
                    ? 'bg-blue-50 border-blue-200 text-blue-600 font-bold' 
                    : 'bg-gray-50 border-transparent text-gray-500 hover:bg-gray-100 hover:border-gray-200'
                }`}
              >
                <div className="flex items-center gap-2">
                  <Filter size={18} />
                  <span>{selectedCategory}</span>
                </div>
                <ChevronDown size={14} className={`transition-transform duration-200 ${showCategoryMenu ? 'rotate-180' : ''}`} />
              </button>

              {showCategoryMenu && (
                <>
                  <div className="fixed inset-0 z-10" onClick={() => setShowCategoryMenu(false)}></div>
                  <div className="absolute right-0 mt-2 w-48 bg-white border border-gray-100 rounded-2xl shadow-xl z-20 py-2 animate-in fade-in zoom-in-95 duration-200">
                    <p className="px-4 py-2 text-[10px] font-bold text-gray-400 uppercase tracking-wider">Pilih Kategori</p>
                    {categories.map(cat => (
                      <button
                        key={cat}
                        onClick={() => {
                          setSelectedCategory(cat);
                          setShowCategoryMenu(false);
                        }}
                        className="w-full flex items-center justify-between px-4 py-2.5 text-sm text-gray-700 hover:bg-blue-50 hover:text-blue-600 transition-colors"
                      >
                        {cat}
                        {selectedCategory === cat && <Check size={14} />}
                      </button>
                    ))}
                  </div>
                </>
              )}
            </div>

            {/* Sort Toggle */}
            <button 
              onClick={toggleSort}
              className={`flex-1 md:flex-none flex items-center justify-center gap-2 px-4 py-2.5 rounded-xl transition-all border ${
                sortOrder !== 'none'
                  ? 'bg-blue-50 border-blue-200 text-blue-600 font-bold'
                  : 'bg-gray-50 border-transparent text-gray-500 hover:bg-gray-100 hover:border-gray-200'
              }`}
            >
              {sortOrder === 'desc' ? <SortDesc size={18} /> : (sortOrder === 'asc' ? <SortAsc size={18} /> : <ArrowUpDown size={18} />)}
              <span>{sortOrder === 'none' ? 'Abjad' : (sortOrder === 'asc' ? 'A-Z' : 'Z-A')}</span>
            </button>
          </div>
        </div>

        <div className="overflow-x-auto custom-scrollbar">
          <table className="w-full text-left">
            <thead>
              <tr className="bg-gray-50 text-gray-500 text-xs font-bold uppercase tracking-wider">
                <th className="px-6 py-4">Produk</th>
                <th className="px-6 py-4">Kategori</th>
                <th className="px-6 py-4">Harga</th>
                <th className="px-6 py-4">Stok Saat Ini</th>
                <th className="px-6 py-4">Status</th>
                <th className="px-6 py-4 text-center">Aksi</th>
              </tr>
            </thead>
            <tbody className="divide-y divide-gray-100">
              {processedProducts.length > 0 ? (
                processedProducts.map(product => (
                  <tr key={product.id} className="hover:bg-gray-50/50 transition-colors group">
                    <td className="px-6 py-5">
                      <div className="flex items-center gap-3">
                        <div className="w-10 h-10 bg-blue-50 rounded-xl flex items-center justify-center text-blue-600 font-bold">
                          {product.name.charAt(0)}
                        </div>
                        <span className="font-semibold text-gray-800">{product.name}</span>
                      </div>
                    </td>
                    <td className="px-6 py-5">
                      <span className="px-2.5 py-1 bg-gray-100 text-gray-600 text-xs font-bold rounded-lg uppercase">
                        {product.category}
                      </span>
                    </td>
                    <td className="px-6 py-5">
                      <span className="font-bold text-gray-900">{formatCurrency(product.price)}</span>
                    </td>
                    <td className="px-6 py-5">
                      {editingId === product.id ? (
                        <div className="flex items-center gap-2">
                          <input 
                             type="number"
                             className="w-20 p-2 border border-blue-200 rounded-lg focus:outline-none focus:ring-2 focus:ring-blue-500 text-gray-900 font-bold"
                             placeholder="+/-"
                             value={stockAmount}
                             onChange={(e) => setStockAmount(e.target.value)}
                             autoFocus
                          />
                          <button 
                            onClick={() => handleUpdateStock(product.id)}
                            className="p-2 bg-blue-600 text-white rounded-lg hover:bg-blue-700 transition-colors"
                          >
                            <Check size={16} />
                          </button>
                        </div>
                      ) : (
                        <div className="flex items-center gap-2">
                          <span className={`font-bold ${product.stock <= product.minStock ? 'text-red-600' : 'text-gray-700'}`}>
                            {product.stock} {product.unit}
                          </span>
                          <button 
                             onClick={() => setEditingId(product.id)}
                             className="opacity-0 group-hover:opacity-100 p-1.5 text-blue-500 hover:bg-blue-50 rounded-lg transition-all"
                             title="Update Stok Cepat"
                          >
                            <Plus size={16} />
                          </button>
                        </div>
                      )}
                    </td>
                    <td className="px-6 py-5">
                      {product.stock <= product.minStock ? (
                        <span className="px-3 py-1 bg-red-50 text-red-600 rounded-full text-[10px] font-black uppercase tracking-wider flex items-center gap-1 w-fit border border-red-100">
                          Low Stock
                        </span>
                      ) : (
                        <span className="px-3 py-1 bg-green-50 text-green-600 rounded-full text-[10px] font-black uppercase tracking-wider flex items-center gap-1 w-fit border border-green-100">
                          Tersedia
                        </span>
                      )}
                    </td>
                    <td className="px-6 py-5">
                      <div className="flex items-center justify-center gap-2">
                        <button className="p-2 text-gray-400 hover:text-blue-600 hover:bg-blue-50 rounded-lg transition-all">
                          <Edit2 size={18} />
                        </button>
                        <button className="p-2 text-gray-400 hover:text-red-600 hover:bg-red-50 rounded-lg transition-all">
                          <Trash2 size={18} />
                        </button>
                      </div>
                    </td>
                  </tr>
                ))
              ) : (
                <tr>
                  <td colSpan={6} className="px-6 py-20 text-center">
                    <div className="flex flex-col items-center justify-center text-gray-400 italic">
                      <PackagePlus size={48} className="mb-4 opacity-20" />
                      <p>Tidak ada produk yang sesuai kriteria.</p>
                    </div>
                  </td>
                </tr>
              )}
            </tbody>
          </table>
        </div>
      </div>
    </div>
  );
};

export default Inventory;

import React, { useState } from 'react';
import { Search, Calendar, Download, Eye, FileSpreadsheet, X } from 'lucide-react';
import { Transaction } from '../types';
import { formatCurrency, formatDate, exportToCSV } from '../utils';

interface HistoryProps {
  transactions: Transaction[];
}

const History: React.FC<HistoryProps> = ({ transactions }) => {
  const [searchTerm, setSearchTerm] = useState('');
  const [filterDate, setFilterDate] = useState('');

  const filteredTransactions = transactions.filter(t => {
    // Pencarian berdasarkan ID (case insensitive)
    const matchesSearch = t.id.toLowerCase().includes(searchTerm.toLowerCase());

    // Filter berdasarkan tanggal (ISO string t.date dimulai dengan YYYY-MM-DD dari filterDate)
    const matchesDate = filterDate ? t.date.startsWith(filterDate) : true;

    return matchesSearch && matchesDate;
  }).sort((a, b) => new Date(b.date).getTime() - new Date(a.date).getTime());

  const handleExport = () => {
    const dataToExport = filteredTransactions.map(t => ({
      ID: t.id,
      Tanggal: formatDate(t.date),
      Total: t.total,
      Metode: t.paymentMethod,
      Produk: t.items.map(i => `${i.name} (${i.quantity})`).join('; ')
    }));
    exportToCSV(dataToExport, `Laporan-Penjualan-${new Date().toISOString().split('T')[0]}.csv`);
  };

  const resetFilters = () => {
    setSearchTerm('');
    setFilterDate('');
  };

  return (
    <div className="space-y-6 animate-in fade-in duration-500">
      <header className="flex flex-col md:flex-row md:items-center justify-between gap-4">
        <div>
          <h2 className="text-2xl font-bold text-gray-800">Riwayat Transaksi</h2>
          <p className="text-gray-500">Lihat dan unduh laporan penjualan toko.</p>
        </div>
        <div className="flex gap-2">
          {(searchTerm || filterDate) && (
            <button 
              onClick={resetFilters}
              className="flex items-center gap-2 px-4 py-3 bg-gray-100 text-gray-600 rounded-xl font-bold hover:bg-gray-200 transition-all"
            >
              <X size={18} />
              Reset
            </button>
          )}
          <button 
            onClick={handleExport}
            className="flex items-center gap-2 px-6 py-3 bg-green-600 text-white rounded-xl font-bold shadow-lg shadow-green-100 hover:bg-green-700 transition-all"
          >
            <FileSpreadsheet size={20} />
            Ekspor CSV
          </button>
        </div>
      </header>

      <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
        <div className="relative">
          <Search className="absolute left-4 top-1/2 -translate-y-1/2 text-gray-400" size={18} />
          <input 
            type="text" 
            placeholder="Cari ID Transaksi..."
            className="w-full pl-11 pr-4 py-3 bg-white border border-gray-100 rounded-2xl shadow-sm focus:outline-none focus:ring-2 focus:ring-blue-500 text-gray-900 font-medium"
            value={searchTerm}
            onChange={(e) => setSearchTerm(e.target.value)}
          />
        </div>
        <div className="relative">
          <Calendar className="absolute left-4 top-1/2 -translate-y-1/2 text-gray-400" size={18} />
          <input 
            type="date" 
            className="w-full pl-11 pr-4 py-3 bg-white border border-gray-100 rounded-2xl shadow-sm focus:outline-none focus:ring-2 focus:ring-blue-500 text-gray-900 font-medium"
            value={filterDate}
            onChange={(e) => setFilterDate(e.target.value)}
          />
        </div>
      </div>

      <div className="bg-white rounded-3xl border border-gray-100 shadow-sm overflow-hidden">
        <div className="overflow-x-auto custom-scrollbar">
          <table className="w-full text-left">
            <thead>
              <tr className="bg-gray-50 text-gray-500 text-xs font-bold uppercase tracking-wider">
                <th className="px-6 py-4">ID Transaksi</th>
                <th className="px-6 py-4">Tanggal & Waktu</th>
                <th className="px-6 py-4">Total Penjualan</th>
                <th className="px-6 py-4">Metode Bayar</th>
                <th className="px-6 py-4 text-center">Aksi</th>
              </tr>
            </thead>
            <tbody className="divide-y divide-gray-100">
              {filteredTransactions.length > 0 ? (
                filteredTransactions.map(trx => (
                  <tr key={trx.id} className="hover:bg-gray-50 transition-colors">
                    <td className="px-6 py-5">
                      <span className="font-mono font-bold text-gray-800">{trx.id}</span>
                    </td>
                    <td className="px-6 py-5 text-gray-600 text-sm">
                      {formatDate(trx.date)}
                    </td>
                    <td className="px-6 py-5">
                      <span className="font-black text-blue-600">{formatCurrency(trx.total)}</span>
                    </td>
                    <td className="px-6 py-5">
                      <div className="flex flex-col">
                        <span className="px-3 py-1 bg-blue-50 text-blue-600 rounded-full text-[10px] font-black uppercase tracking-wider w-fit">
                          {trx.paymentMethod}
                        </span>
                        {trx.paymentProvider && trx.paymentProvider !== 'Tunai' && (
                          <span className="text-[10px] text-gray-400 mt-1 ml-1 font-bold">{trx.paymentProvider}</span>
                        )}
                      </div>
                    </td>
                    <td className="px-6 py-5">
                      <div className="flex justify-center items-center gap-2">
                        <button className="p-2 text-gray-400 hover:text-blue-600 hover:bg-blue-50 rounded-lg transition-all">
                          <Eye size={18} />
                        </button>
                        <button className="p-2 text-gray-400 hover:text-green-600 hover:bg-green-50 rounded-lg transition-all">
                          <Download size={18} />
                        </button>
                      </div>
                    </td>
                  </tr>
                ))
              ) : (
                <tr>
                  <td colSpan={5} className="px-6 py-20 text-center">
                    <div className="flex flex-col items-center justify-center text-gray-400 italic">
                      <Search size={48} className="mb-4 opacity-20" />
                      <p>Tidak ada transaksi yang ditemukan.</p>
                      {(searchTerm || filterDate) && (
                        <button 
                          onClick={resetFilters}
                          className="mt-4 text-blue-600 font-bold not-italic hover:underline"
                        >
                          Hapus semua filter
                        </button>
                      )}
                    </div>
                  </td>
                </tr>
              )}
            </tbody>
          </table>
        </div>
      </div>
    </div>
  );
};

